mapper.select:
SELECT sc.*, s.name AS student_name, s.student_no, c.course_name FROM score sc LEFT JOIN student s ON sc.student_id = s.id LEFT JOIN course c ON sc.course_id = c.id WHERE sc.deleted = 0
AND ( (scope.selfOnly AND s.user_id = scope.userId) OR (scope.departmentId != null AND s.department_id = scope.departmentId) OR (scope.hasClassIds AND s.clazz_id IN #{id}) OR (scope.teacherId != null AND c.teacher_id = scope.teacherId) OR (scope.hasCourseIds AND sc.course_id IN #{id}) )
AND sc.student_id = #{studentId}
AND sc.course_id = #{courseId}
AND s.clazz_id = #{clazzId}
ORDER BY sc.id DESC

SELECT s.student_no AS studentNo, s.name AS studentName, c.course_name AS courseName, sc.score AS score, sc.exam_time AS examTime FROM score sc JOIN student s ON sc.student_id = s.id JOIN course c ON sc.course_id = c.id WHERE sc.deleted = 0
AND ( (scope.selfOnly AND s.user_id = scope.userId) OR (scope.departmentId != null AND s.department_id = scope.departmentId) OR (scope.hasClassIds AND s.clazz_id IN #{id}) OR (scope.teacherId != null AND c.teacher_id = scope.teacherId) OR (scope.hasCourseIds AND sc.course_id IN #{id}) )
AND sc.student_id = #{studentId}
AND sc.course_id = #{courseId}
AND s.clazz_id = #{clazzId}
ORDER BY sc.id DESC

SELECT student_id AS studentId, course_id AS courseId FROM score WHERE deleted = 0 AND student_id IN
#{studentId}
AND course_id IN
#{courseId}

SELECT COALESCE(ROUND(AVG(sc.score), 2), 0) AS avg, COALESCE(MAX(sc.score), 0) AS max, COALESCE(MIN(sc.score), 0) AS min, COALESCE(ROUND(SUM(CASE WHEN sc.score >= 60 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2), 0) AS passRate FROM score sc LEFT JOIN student s ON sc.student_id = s.id LEFT JOIN course c ON sc.course_id = c.id WHERE sc.deleted = 0
AND ( (scope.selfOnly AND s.user_id = scope.userId) OR (scope.departmentId != null AND s.department_id = scope.departmentId) OR (scope.hasClassIds AND s.clazz_id IN #{id}) OR (scope.teacherId != null AND c.teacher_id = scope.teacherId) OR (scope.hasCourseIds AND sc.course_id IN #{id}) )
AND sc.student_id = #{studentId}
AND sc.course_id = #{courseId}
AND s.clazz_id = #{clazzId}

SELECT COALESCE(SUM(CASE WHEN t.best_score >= 60 THEN c.credit ELSE 0 END), 0) AS earnedCredits, COALESCE(SUM(c.credit), 0) AS totalCredits, SUM(CASE WHEN t.best_score >= 60 THEN 1 ELSE 0 END) AS passCount, SUM(CASE WHEN t.best_score < 60 THEN 1 ELSE 0 END) AS failCount, COUNT(*) AS courseCount FROM ( SELECT sc.course_id, MAX(sc.score) AS best_score FROM score sc WHERE sc.deleted = 0 AND sc.active = 1 AND sc.score_status = 'APPROVED' AND sc.student_id = #{studentId}
AND EXISTS (SELECT 1 FROM course_term ct WHERE ct.id = sc.course_term_id AND ct.term_id = #{termId})
GROUP BY sc.course_id ) t JOIN course c ON c.id = t.course_id AND c.deleted = 0

SELECT s.id AS studentId, s.student_no AS studentNo, s.name AS studentName, COALESCE(SUM(CASE WHEN t.best_score >= 60 THEN c.credit ELSE 0 END), 0) AS earnedCredits, COUNT(t.course_id) AS courseCount, SUM(CASE WHEN t.best_score < 60 THEN 1 ELSE 0 END) AS failCount FROM student s LEFT JOIN ( SELECT sc.student_id, sc.course_id, MAX(sc.score) AS best_score FROM score sc WHERE sc.deleted = 0 AND sc.active = 1 AND sc.score_status = 'APPROVED' GROUP BY sc.student_id, sc.course_id ) t ON t.student_id = s.id LEFT JOIN course c ON c.id = t.course_id AND c.deleted = 0 WHERE s.deleted = 0 AND s.clazz_id = #{clazzId}
AND (t.course_id IS NULL OR EXISTS ( SELECT 1 FROM score sc2 JOIN course_term ct2 ON ct2.id = sc2.course_term_id WHERE sc2.student_id = s.id AND sc2.course_id = t.course_id AND sc2.deleted = 0 AND sc2.active = 1 AND sc2.score_status = 'APPROVED' AND ct2.term_id = #{termId}))
GROUP BY s.id, s.student_no, s.name ORDER BY s.student_no
